(function() {
    'use strict';

    class OrgChartAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Org Chart Game`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, tag: `r1_tag`, title: `r1_title`, brief: `r1_brief`, teaches: `r1_teaches`, panel: `round1Panel` },
                { id: 2, tag: `r2_tag`, title: `r2_title`, brief: `r2_brief`, teaches: `r2_teaches`, panel: `round2Panel` },
                { id: 3, tag: `r3_tag`, title: `r3_title`, brief: `r3_brief`, teaches: `r3_teaches`, panel: `round3Panel` },
                { id: 4, tag: `r4_tag`, title: `r4_title`, brief: `r4_brief`, teaches: `r4_teaches`, panel: `round4Panel` },
                { id: 5, tag: `r5_tag`, title: `r5_title`, brief: `r5_brief`, teaches: `r5_teaches`, panel: `round5Panel` }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    roundsPassed: 0,
                    scoreHistory: [],
                    decSpeed: 50,
                    commSpeed: 50,
                    mgmtCost: 12,
                    starLevel: 0,
                    lastLayers: 3,
                    lastSpan: 6,
                    lastStructure: `functional`
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    action: `none`,
                    span: 12,
                    layers: 3,
                    structure: `functional`,
                    pricing: `centralised`,
                    design: `centralised`,
                    hiring: `centralised`,
                    marketing: `centralised`,
                    finance: `centralised`,
                    finalLayers: 4,
                    finalSpan: 6,
                    finalStructure: `divisional`,
                    finalDelegation: `medium`
                };
            }
            this._updateBriefing(state);
            this._updateDiagram(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            this._updateBriefing(state);
            var round = state.currentPeriod;

            if (round === 1) {
                var actSel = document.getElementById(`actionSelect`);
                var spanIn = document.getElementById(`spanInput`);
                if (actSel) decisions.action = actSel.value;
                if (spanIn) decisions.span = parseInt(spanIn.value, 10);
                if (!decisions.span || decisions.span < 1 || decisions.span > 12) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t(`span_warning`), `warning`
                    );
                    return false;
                }
            } else if (round === 2) {
                var layIn = document.getElementById(`layersInput`);
                if (layIn) decisions.layers = parseInt(layIn.value, 10);
                if (!decisions.layers || decisions.layers < 1 || decisions.layers > 6) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t(`layers_warning`), `warning`
                    );
                    return false;
                }
            } else if (round === 3) {
                var strSel = document.getElementById(`structureSelect`);
                if (strSel) decisions.structure = strSel.value;
            } else if (round === 4) {
                var ids = [`pricing`, `design`, `hiring`, `marketing`, `finance`];
                for (var i = 0; i < ids.length; i++) {
                    var el = document.getElementById(ids[i] + `Select`);
                    if (el) decisions[ids[i]] = el.value;
                }
            } else if (round === 5) {
                var fl = document.getElementById(`finalLayersInput`);
                var fs = document.getElementById(`finalSpanInput`);
                var fst = document.getElementById(`finalStructureSelect`);
                var fd = document.getElementById(`finalDelegationSelect`);
                if (fl) decisions.finalLayers = parseInt(fl.value, 10);
                if (fs) decisions.finalSpan = parseInt(fs.value, 10);
                if (fst) decisions.finalStructure = fst.value;
                if (fd) decisions.finalDelegation = fd.value;
                if (!decisions.finalLayers || decisions.finalLayers < 1 || decisions.finalLayers > 6) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t(`final_warning`), `warning`
                    );
                    return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var round = state.currentPeriod;
            var score = 0;
            var feedbackKey = `fb_generic`;
            var decSpeed = state.domainState.decSpeed;
            var commSpeed = state.domainState.commSpeed;
            var mgmtCost = state.domainState.mgmtCost;
            var layersNow = state.domainState.lastLayers;
            var spanNow = state.domainState.lastSpan;
            var structNow = state.domainState.lastStructure;

            if (round === 1) {
                var actionPts = 0;
                if (d.action === `both`) actionPts = 40;
                else if (d.action === `delegate` || d.action === `layer`) actionPts = 20;
                else actionPts = 0;

                var spanPts = 0;
                if (d.span <= 6 && d.span >= 3) spanPts = 60;
                else if (d.span <= 8) spanPts = 30;
                else spanPts = 0;

                score = actionPts + spanPts;

                if (d.action === `both`) layersNow = 2;
                else if (d.action === `layer`) layersNow = 2;
                spanNow = d.span;

                decSpeed = d.action === `both` || d.action === `delegate` ? 75 : (d.action === `layer` ? 55 : 35);
                commSpeed = d.span <= 6 ? 70 : (d.span <= 8 ? 55 : 35);
                mgmtCost = 9 + (layersNow - 1) * 1.5;

                feedbackKey = score >= 80 ? `fb_r1_great` : (score >= 50 ? `fb_r1_ok` : `fb_r1_weak`);

            } else if (round === 2) {
                if (d.layers === 2) score = 100;
                else if (d.layers === 3) score = 65;
                else if (d.layers === 4) score = 45;
                else if (d.layers === 1) score = 35;
                else score = 15;

                layersNow = d.layers;
                decSpeed = Math.max(30, 95 - d.layers * 12);
                commSpeed = Math.max(30, 100 - d.layers * 13);
                mgmtCost = 7 + d.layers * 2;
                feedbackKey = score >= 80 ? `fb_r2_great` : (score >= 50 ? `fb_r2_ok` : `fb_r2_weak`);

            } else if (round === 3) {
                if (d.structure === `divisional`) score = 100;
                else if (d.structure === `matrix`) score = 85;
                else if (d.structure === `hybrid`) score = 70;
                else score = 25;

                structNow = d.structure;
                decSpeed = (d.structure === `divisional` || d.structure === `hybrid`) ? 75 : (d.structure === `matrix` ? 55 : 45);
                commSpeed = (d.structure === `matrix`) ? 55 : 65;
                mgmtCost = (d.structure === `matrix`) ? 14 : (d.structure === `divisional` ? 12 : 11);
                feedbackKey = score >= 85 ? `fb_r3_great` : (score >= 60 ? `fb_r3_ok` : `fb_r3_weak`);

            } else if (round === 4) {
                var pts = 0;
                pts += (d.pricing === `centralised`) ? 18 : 12;
                pts += (d.design === `decentralised`) ? 22 : 6;
                pts += (d.hiring === `decentralised`) ? 18 : 10;
                pts += (d.marketing === `decentralised`) ? 22 : 6;
                pts += (d.finance === `centralised`) ? 20 : 4;
                score = pts;

                var decentCount = [d.pricing, d.design, d.hiring, d.marketing, d.finance]
                    .filter(function(v) { return v === `decentralised`; }).length;
                decSpeed = 45 + decentCount * 8;
                commSpeed = 60;
                mgmtCost = 11 + (5 - decentCount) * 0.4;
                feedbackKey = score >= 85 ? `fb_r4_great` : (score >= 65 ? `fb_r4_ok` : `fb_r4_weak`);

            } else if (round === 5) {
                var layerPts = 0;
                if (d.finalLayers >= 3 && d.finalLayers <= 5) layerPts = 35;
                else if (d.finalLayers === 2 || d.finalLayers === 6) layerPts = 18;
                else layerPts = 5;

                var spanPts2 = 0;
                if (d.finalSpan >= 4 && d.finalSpan <= 8) spanPts2 = 30;
                else if (d.finalSpan === 3 || d.finalSpan === 9) spanPts2 = 15;
                else spanPts2 = 5;

                var structPts = 0;
                if (d.finalStructure === `divisional` || d.finalStructure === `matrix` || d.finalStructure === `hybrid`) structPts = 20;
                else structPts = 8;

                var delPts = 0;
                if (d.finalDelegation === `medium`) delPts = 15;
                else if (d.finalDelegation === `high`) delPts = 12;
                else delPts = 5;

                score = layerPts + spanPts2 + structPts + delPts;

                layersNow = d.finalLayers;
                spanNow = d.finalSpan;
                structNow = d.finalStructure;
                decSpeed = Math.min(90, 45 + (d.finalDelegation === `high` ? 25 : (d.finalDelegation === `medium` ? 15 : 5)) + (d.finalSpan > 6 ? 10 : 5));
                commSpeed = Math.max(30, 95 - d.finalLayers * 10);
                mgmtCost = 7 + d.finalLayers * 1.8;

                feedbackKey = score >= 85 ? `fb_r5_great` : (score >= 65 ? `fb_r5_ok` : `fb_r5_weak`);
            }

            state.domainState.totalScore += score;
            state.domainState.scoreHistory.push(score);
            if (score >= 70) state.domainState.roundsPassed += 1;
            state.domainState.decSpeed = decSpeed;
            state.domainState.commSpeed = commSpeed;
            state.domainState.mgmtCost = mgmtCost;
            state.domainState.lastLayers = layersNow;
            state.domainState.lastSpan = spanNow;
            state.domainState.lastStructure = structNow;

            var stars = 1;
            if (state.currentPeriod === 5) {
                if (state.domainState.roundsPassed >= 4) stars = 2;
                if (state.domainState.roundsPassed === 5 && score >= 85) stars = 3;
                state.domainState.starLevel = stars;
            }

            // v1.1.0: persist a normalized 0-100 overall score + performance so the
            // reporting layer resolves a headline score (express_resolveDomainScore →
            // domainState.performance.overallScore) — per-round results.score already
            // feeds the timeline, but the domain-level score was previously null.
            var _rounds = state.domainState.scoreHistory.length || 1;
            var _overall = Math.round(state.domainState.totalScore / _rounds);
            var _passed = state.domainState.roundsPassed;
            var _pstars = 1;
            if (_passed >= 4) _pstars = 2;
            if (_passed === this.ROUNDS.length && score >= 85) _pstars = 3;
            var _grade = _pstars === 3 ? `COO` : (_pstars === 2 ? `Organisational Designer` : `Manager`);
            state.domainState.score = _overall;
            state.domainState.performance = { overallScore: _overall, grade: _grade, stars: _pstars };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
                self._updateDiagram(state);
                self._updateStarsDisplay(state);
            }, 450);

            return {
                period: state.currentPeriod,
                score: score,
                totalScore: state.domainState.totalScore,
                decSpeed: Math.round(decSpeed),
                commSpeed: Math.round(commSpeed),
                mgmtCost: Number(mgmtCost.toFixed(1)),
                layers: layersNow,
                span: spanNow,
                structure: structNow,
                feedbackKey: feedbackKey,
                overallScore: _overall,
                stars: _pstars
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`scoreDisplay`, `domainState.totalScore`, function(v) { return Math.round(v); });
            uiManager.bind(`decSpeedDisplay`, `domainState.decSpeed`, function(v) { return Math.round(v) + `%`; });
            uiManager.bind(`commSpeedDisplay`, `domainState.commSpeed`, function(v) { return Math.round(v) + `%`; });
