        getPerformanceSummary(history) {
            if (!history.length) return {};
            var total = history.reduce(function(s, r) { return s + ((r.results && r.results.score) || 0); }, 0);
            var avg = total / history.length;
            var passed = history.filter(function(r) { return r.results && r.results.score >= 70; }).length;

            var stars = 1;
            if (passed >= 4) stars = 2;
            if (passed === history.length && avg >= 80) stars = 3;

            var title = `Manager`;
            if (stars === 2) title = `Organisational Designer`;
            if (stars === 3) title = `COO`;

            var insights = [];
            if (avg >= 80) insights.push(window.mySimulation.t(`insight_strong`));
            else if (avg >= 60) insights.push(window.mySimulation.t(`insight_ok`));
            else insights.push(window.mySimulation.t(`insight_weak`));
            insights.push(window.mySimulation.t(`insight_debrief`));

            return {
                totalScore: total,
                avgScore: Math.round(avg),
                overallScore: Math.round(avg),
                roundsPassed: passed,
                totalPeriods: history.length,
                stars: stars,
                title: title,
                performance: title,
                insights: insights
            };
        }

